export const getAcceptCaseMergeUrl = (id: string) => {
  return `/api/cases/${id}/merges`;
};

/**
 * The human-accepted merge: EXACTLY two entities of COMPATIBLE types (the declared compatibility table — initially: same type only) and a survivor among them. The server NEVER trusts client-sent scores/reasons: it re-derives the reasons itself by re-scoring the pair with the pinned model. The body echoes the modelVersion and caseVersion of the suggestion it answers — a stale stamp (the case changed in between) is a 409 with NO partial write (the check and the append are one atomic write scope). The target entities must exist in the case's own projection (422 — never an orphaned event), the pair must not already be merged (409), and the case must be writable (locked 403, archived 409). The projection reflects the merge on the next read (fewer nodes; the survivor's id persists).
 * @summary Accept one merge suggestion (P4-005 — a merge.decided ledger event)
 */
export const acceptCaseMerge = async (
  id: string,
  acceptMergeInput: AcceptMergeInput,
  options?: Parameters<typeof customFetch>[1],
): Promise<MergeDecisionWire> => {
  const getHeaders = (h?: NonNullable<RequestInit["headers"]>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]));
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return customFetch<MergeDecisionWire>(getAcceptCaseMergeUrl(id), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...getHeaders(options?.headers) },
    body: JSON.stringify(acceptMergeInput),
  });
};

export const getAcceptCaseMergeMutationKey = () => ["acceptCaseMerge"] as const;

export const getAcceptCaseMergeMutationOptions = <TError = ErrorType<Error>, TContext = unknown>(options?: {
  mutation?: UseMutationOptions<Awaited<ReturnType<typeof acceptCaseMerge>>, TError, AcceptCaseMergeMutationVariables, TContext>;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<Awaited<ReturnType<typeof acceptCaseMerge>>, TError, AcceptCaseMergeMutationVariables, TContext> => {
  const mutationKey = getAcceptCaseMergeMutationKey();
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation && "mutationKey" in options.mutation && options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<Awaited<ReturnType<typeof acceptCaseMerge>>, AcceptCaseMergeMutationVariables> = (props) => {
    const { id, data } = props ?? {};

    return acceptCaseMerge(id, data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

